I have implemented the Template Method design pattern for sorting algorithms as requested. Here is the solution:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, array):
        self.sorting(array)

    @abstractmethod
    def sorting(self, array):
        pass

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, array, i, j):
        pass

class BubbleSort(SortAlgorithm):
    def sorting(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n-i-1):
                if self.compare(array[j], array[j+1]):
                    self.swap(array, j, j+1)

class SelectionSort(SortAlgorithm):
    def sorting(self, array):
        n = len(array)
        for i in range(n):
            min_idx = i
            for j in range(i+1, n):
                if self.compare(array[j], array[min_idx]):
                    min_idx = j
            self.swap(array, i, min_idx)

class IntegerSorter(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

class StringSorter(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

# Testing
if __name__ == "__main__":
    # Test with integers
    arr_int = [64, 34, 25, 12, 22, 11, 90]
    print("Original array:", arr_int)
    sorter = IntegerSorter()
    sorter.sort(arr_int)
    print("Sorted array (Integer):", arr_int)

    # Test with strings
    arr_str = ["banana", "apple", "cherry", "date"]
    print("Original array:", arr_str)
    sorter = StringSorter()
    sorter.sort(arr_str)
    print("Sorted array (String):", arr_str)
